#include <iostream>
#include <iomanip>
#include <limits>

using namespace std;

int main() {
    int N;
    cin >> N;

    double best = numeric_limits<double>::max();

    for (int i = 0; i < N; ++i) {
        double P;
        int G;
        cin >> P >> G;

        double pricePerKg = P * 1000.0 / G;
        if (pricePerKg < best) {
            best = pricePerKg;
        }
    }

    cout << fixed << setprecision(2) << best << endl;

    return 0;
}
